solution:
interface Produit {
  readonly id: number;
  nom: string;
}

function renommer(p: Produit, nom: string): Produit {
  p.nom = nom;
  return p;
}

interface Ligne {
  produit: string;
  prix: number;
  quantite: number;
}

interface Commande {
  readonly id: number;
  client: string;
  lignes: Ligne[];
  livraison?: boolean;
}

function total(c: Commande): number {
  const somme = c.lignes.reduce((s, l) => s + l.prix * l.quantite, 0);
  return c.livraison ? somme + 1500 : somme;
}
